questionvariables.text:
ordergreat(a,b,c,d);
validate_numeric(ex) := block([sx], sx: ev(ex, simp), if listofvars(ex) = [] and freeof(%i, sx) then "" else "Type a number in each box, not a letter.");
/* Design: matrix from an object and its image. Source: original. det M in {1, 2, 4} up to sign and det of the object matrix in {1, 2, 4, 5} up to sign, so M^-1 and the reversed product have terminating entries. */
plist: [[matrix([2,0],[4,-2]),[1,-1],[0,4]],[matrix([4,3],[4,2]),[-2,-2],[3,2]],[matrix([0,4],[1,-2]),[0,-1],[-2,1]],[matrix([2,-1],[2,-2]),[0,2],[2,2]],[matrix([2,1],[2,0]),[3,-1],[4,-2]],[matrix([0,1],[4,4]),[-1,1],[-2,3]],[matrix([4,4],[-2,-3]),[0,-2],[-2,3]],[matrix([4,1],[4,2]),[1,-1],[0,2]],[matrix([-2,1],[-2,0]),[1,1],[0,-2]],[matrix([-1,1],[-2,0]),[-2,3],[1,-2]]];
ix: 1+rand(10);
ta: plist[ix][1]; Pp: plist[ix][2]; Qp: plist[ix][3];
Ob: transpose(matrix(Pp,Qp)); Im: ta.Ob;
Pi: [Im[1,1],Im[2,1]]; Qi: [Im[1,2],Im[2,2]];
/* diagnostics: transpose; the inverse (image to object); object inverse on the wrong side */
dT: transpose(ta); dI: invert(ta); dW: invert(Ob).Im;
tr: Im.invert(Ob);
tw: ta+matrix([0,1],[0,0]);
e1: Pp[1]*a+Pp[2]*b = Pi[1]; e2: Qp[1]*a+Qp[2]*b = Qi[1];
e3: Pp[1]*c+Pp[2]*d = Pi[2]; e4: Qp[1]*c+Qp[2]*d = Qi[2];
dO: determinant(Ob); iO: invert(Ob);
